import{_ as t,c as a,o as n,a3 as i}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Equipment","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/equipment/index.md","filePath":"master/supply-chain/maintenance/equipment/index.md","lastUpdated":1793074831000}'),r={name:"master/supply-chain/maintenance/equipment/index.md"};function o(s,e,l,h,c,p){return n(),a("div",null,e[0]||(e[0]=[i('<h1 id="equipment" tabindex="-1">Equipment <a class="header-anchor" href="#equipment" aria-label="Permalink to &quot;Equipment&quot;">​</a></h1><p>Equipment is any machine, tool or device your company needs to keep working. It can be a hydraulic press on the shop floor, a forklift, an office computer or a server. You can own it, or use it under a contract with a third party. Each equipment record stores what the item is, where it is, who looks after it and when its warranty ends.</p><blockquote><p><strong>In simple words:</strong> Equipment is the list of things you take care of. Every repair or check-up is raised against one of them.</p></blockquote><h2 id="how-equipment-fits-in-the-module" tabindex="-1">How equipment fits in the module <a class="header-anchor" href="#how-equipment-fits-in-the-module" aria-label="Permalink to &quot;How equipment fits in the module&quot;">​</a></h2><p>Equipment connects to the other parts of Maintenance:</p><ul><li><strong>Category.</strong> Groups similar equipment, for example Packaging Machines. The category also holds a default Responsible person. See <a href="./../setup/equipment-categories.html">Equipment categories</a>.</li><li><strong>Team.</strong> The group of people who look after the equipment, for example Electrical Maintenance Team. See <a href="./../setup/maintenance-teams.html">Maintenance teams</a>.</li><li><strong>Requests.</strong> A request describes a breakdown (corrective) or a planned check (preventive). When you pick the equipment on a request, the category, team and responsible person fill in for you. See <a href="./../requests/">Requests</a>.</li><li><strong>Calendar.</strong> Requests with a scheduled date appear on the <a href="./../calendar/maintenance-calendar.html">Maintenance calendar</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Create the category and the team first. Then add the equipment, so you can pick both on the equipment form.</p></div><h2 id="running-example" tabindex="-1">Running example <a class="header-anchor" href="#running-example" aria-label="Permalink to &quot;Running example&quot;">​</a></h2><p>The pages in this module follow one example. The category is <strong>Packaging Machines</strong>, the team is <strong>Electrical Maintenance Team</strong>, and the equipment is <strong>Hydraulic Press 200T</strong>. The technician for all three is Linda Ndlovu.</p><h2 id="in-this-section" tabindex="-1">In this section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In this section&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What you learn</th></tr></thead><tbody><tr><td><a href="./add-equipment.html">Add equipment</a></td><td>Fill in every field of the equipment form and save it.</td></tr><tr><td><a href="./manage-equipment.html">Manage equipment</a></td><td>Use the list tabs, filters, grouping and search. Archive, restore and delete equipment.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../setup/equipment-categories.html">Equipment categories</a></li><li><a href="./../setup/maintenance-teams.html">Maintenance teams</a></li><li><a href="./../requests/create-request.html">Create a maintenance request</a></li></ul>',13)]))}const d=t(r,[["render",o]]);export{m as __pageData,d as default};
